use vstd::prelude::*;

verus! {

fn empty(n: u8) -> (result: Vec<f64>)
    ensures
        result.len() == n as usize,
{
    let target: usize = n as usize;
    let mut v: Vec<f64> = Vec::new();

    while v.len() < target
        invariant
            v.len() <= target,
        decreases
            target - v.len(),
    {
        // Any value is allowed; only the length matters.
        v.push(0.0);
    }

    v
}

} // verus!

